package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository logs;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public RateService(RateRepository rates, RateLogRepository logs, SheetRepository sheets, Audit audit,
            RollupService rollup) {
        this.rates = rates;
        this.logs = logs;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /**
     * The sheet's rates, then each parent sheet's up to {@link RollupService#PARENT_LEVELS} levels up (nearest first),
     * each in grade order then by from-date.
     */
    public List<List<Rate>> chain(String sheetId) {
        return rollup.rateChain(sheetId);
    }

    /**
     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time. Empty when the date is before every rate, or
     * after that rate's to-date. With none on the sheet, the parent sheet's, then its parent's, up to three levels up.
     */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return RollupService.rateOn(rollup.rateChain(sheetId), grade, date);
    }

    /**
     * The grade's rate percent in force on the date as the rates stood at the end of {@code asOf}: each from-date's
     * last setting made while the sheet's today was on or before it (a rate set before settings were logged counts as
     * it is now). With none on the sheet then, the parent sheets' rates in force on the date as they stood then.
     * Empty when the grade had no rate in force on the date then.
     */
    public Optional<BigDecimal> rateAsOf(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        List<Rate> stood = RateLog.stood(sheetId, grade, rates.findBySheetIdAndGrade(sheetId, grade),
                logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade), asOf);
        Optional<BigDecimal> own = stood.stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date))
                .map(Rate::getPct);
        if (own.isPresent()) {
            return own;
        }
        List<List<Rate>> chain = rollup.rateChain(sheetId, asOf);
        return RollupService.rateOn(chain.subList(1, chain.size()), grade, date).map(Rate::getPct);
    }

    /** What the grade having the percent on every date would change on the sheet; nothing is saved. */
    @Transactional(readOnly = true)
    public RollupService.RatePreview preview(String sheetId, String grade, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        return rollup.preview(sheetId, grade, pct);
    }

    /**
     * Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null: no
     * end), replacing the one it had; a to-date before the from-date is refused.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
            throw new RateDatesException(fromDate, toDate);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, fromDate, pct);
        } else {
            rate.setPct(pct);
        }
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            throw new RateTakenException(sheetId, grade);
        }
        logs.save(new RateLog(saved, sheets.findById(sheetId).orElseThrow().getToday()));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (saved.getFromDate() == null ? "" : " from=" + saved.getFromDate())
                + (saved.getToDate() == null ? "" : " to=" + saved.getToDate()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The rates for each grade on a sheet, each from its from-date. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * A rate as shown: the percent with two decimals, and its from- and to-dates as yyyy-mm-dd (null when it has none);
     * and its level, 0 for the sheet's own, 1 for its parent sheet's, 2 for that sheet's parent's and so on.
     */
    public record RateView(String grade, String pct, String from, String to, int level) {

        static RateView of(Rate rate) {
            return of(rate, 0);
        }

        static RateView of(Rate rate, int level) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    rate.getFromDate() == null ? null : rate.getFromDate().toString(),
                    rate.getToDate() == null ? null : rate.getToDate().toString(), level);
        }
    }

    /**
     * A percent of 0.00 up to 999.99 with up to two decimals, and an optional from-date as yyyy-mm-dd;
     * a blank or missing from-date means the rate applies from the beginning of time. An optional to-date likewise:
     * blank or missing means the rate has no end.
     */
    public record RateRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String pct,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String to) {

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }

        LocalDate fromValue() {
            return date(from);
        }

        LocalDate toValue() {
            return date(to);
        }

        private static LocalDate date(String value) {
            if (value == null || value.isBlank()) {
                return null;
            }
            try {
                return LocalDate.parse(value.trim());
            } catch (DateTimeParseException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + value.trim());
            }
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    /**
     * The sheet's rates in grade order, then by from-date (the undated one first); a grade with no rate is left out.
     * Then, likewise, the rates of its parent sheet, of that sheet's parent and so on up to three levels up, each
     * with its level.
     */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        List<List<Rate>> chain = service.chain(sheetId.trim());
        List<RateView> views = new ArrayList<>();
        for (int level = 0; level < chain.size(); level++) {
            for (Rate rate : chain.get(level)) {
                views.add(RateView.of(rate, level));
            }
        }
        return views;
    }

    /**
     * What setting the grade's rate to the percent on every date would change, saving nothing: how many OPEN and PENDING
     * claims would show a different due, and the sum of the differences.
     */
    @GetMapping("/preview")
    public RollupService.RatePreview preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String pct,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.preview(sheetId.trim(), grade, new BigDecimal(pct.trim()).setScale(2, RoundingMode.UNNECESSARY));
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, request.fromValue(),
                request.toValue(), request.pctValue()));
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A rate's to-date is before its from-date. */
@ResponseStatus(HttpStatus.BAD_REQUEST)
public class RateDatesException extends RuntimeException {

    public RateDatesException(LocalDate fromDate, LocalDate toDate) {
        super("The rate's to-date " + toDate + " is before its from-date " + fromDate);
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Adds or updates a person per pasted line of name,grade,terms,contact, in order, each as the person form would (the
 * terms and the contact may be absent or blank). A line whose name matches a person on the sheet, by name or alias,
 * updates them: their grade is recorded from the sheet's today, and their terms and contact are set when the line
 * gives them. Every other line adds a person. Every line is checked first with the person form's rules, and a person
 * or a contact repeated within the paste is refused too. The whole is one change: if any line is refused, nothing is
 * imported.
 */
@Service
public class ImportPeopleService {

    private static final int MAX_NAME = 200;

    private static final int MAX_CONTACT = 200;

    private record Line(int number, String name, String grade, Integer terms, String contact) {
    }

    /** How many people an import added and how many it updated. */
    public record Result(int added, int updated) {
    }

    private final PersonService people;

    public ImportPeopleService(PersonService people) {
        this.people = people;
    }

    /** How many people were added and how many updated. */
    @Transactional
    public Result importPeople(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        String[] rows = text.split("\\r?\\n");
        for (int i = 0; i < rows.length; i++) {
            if (!rows[i].isBlank()) {
                lines.add(parse(i + 1, rows[i]));
            }
        }
        if (lines.isEmpty()) {
            throw new ImportPeopleException("Paste at least one line of name,grade,terms,contact");
        }
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        List<Person> matches = new ArrayList<>();
        for (Line line : lines) {
            String key = Person.key(line.name());
            Person match = people.findByNameOrAlias(sheetId, line.name()).orElse(null);
            matches.add(match);
            // A person named twice, by their name or an alias, is a repeat as much as a new name given twice.
            if (!names.add(match != null ? "#" + match.getId() : key)
                    || match == null && people.usedInTree(sheetId, key, null)) {
                throw new ImportPeopleException(line.number(), "the name " + line.name().trim() + " is already in use");
            }
            String contactKey = Person.contactKey(line.contact());
            if (contactKey != null && !contacts.add(contactKey)) {
                throw new ImportPeopleException(line.number(), "the contact " + contactKey + " is already in use");
            }
        }
        // Each person is checked again as the person form's are; a refused one rolls back those imported before it.
        int added = 0;
        int updated = 0;
        for (int i = 0; i < lines.size(); i++) {
            Line line = lines.get(i);
            Person match = matches.get(i);
            if (match == null) {
                people.add(sheetId, user, line.name(), line.grade(), line.terms(), line.contact());
                added++;
            } else {
                people.update(sheetId, user, match.getId(), null, match.getName(), line.grade(), null,
                        line.terms() != null ? line.terms() : match.getTerms(),
                        line.contact().isBlank() ? match.getContact() : line.contact());
                updated++;
            }
        }
        return new Result(added, updated);
    }

    private static Line parse(int number, String row) {
        String[] fields = row.split(",", -1);
        if (fields.length < 2 || fields.length > 4) {
            throw new ImportPeopleException(number, "expected name,grade,terms,contact");
        }
        String name = fields[0];
        if (name.isBlank()) {
            throw new ImportPeopleException(number, "the name is blank");
        }
